/**
 * Sintaxe de plural embutida na propria traducao: `{param|singular|plural}`.
 * Exemplo: "{count} {count|card|cards}" -> "1 card" / "3 cards".
 * Idiomas com mais de duas formas usam `{param|uma|poucas|muitas}`.
 */
const PLURAL_PATTERN = /\{([A-Za-z0-9_]+)\|([^{}]*)\}/g;

/**
 * Indice da forma gramatical a usar, conforme as regras de plural do idioma.
 * Baseado nas categorias do CLDR, reduzido ao que os textos do app precisam.
 */
export function pluralFormIndex(language: string, count: number, formCount: number): number {
  if (formCount <= 1) return 0;
  const n = Math.abs(count);
  let index: number;

  switch (language) {
    case "ru": {
      // 1, 21, 31... / 2-4, 22-24... / 0, 5-20, 25-30...
      if (!Number.isInteger(n)) {
        index = 1;
        break;
      }
      const mod10 = n % 10;
      const mod100 = n % 100;
      if (mod10 === 1 && mod100 !== 11) index = 0;
      else if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) index = 1;
      else index = 2;
      break;
    }
    case "ar": {
      // Aproximacao das categorias arabes: singular / dual e 3-10 / demais.
      const mod100 = n % 100;
      if (n === 1) index = 0;
      else if (n === 2 || (Number.isInteger(n) && mod100 >= 3 && mod100 <= 10)) index = 1;
      else index = 2;
      break;
    }
    case "ja":
    case "zh":
      // Sem flexao de numero: usa sempre a ultima forma declarada.
      index = formCount - 1;
      break;
    case "fr":
      // O frances trata 0 e 1 como singular.
      index = n < 2 ? 0 : 1;
      break;
    default:
      index = n === 1 ? 0 : 1;
      break;
  }

  return Math.min(index, formCount - 1);
}

/** Resolve grupos de plural e interpola os parametros de um texto traduzido. */
export function formatTranslation(
  template: string,
  language: string,
  params?: Record<string, string | number>
): string {
  if (!template) return "";
  if (!params) return template;

  let str = template.replace(PLURAL_PATTERN, (match, name: string, forms: string) => {
    const value = Number(params[name]);
    if (!Number.isFinite(value)) return match;
    const options = forms.split("|");
    return options[pluralFormIndex(language, value, options.length)] ?? options[options.length - 1];
  });

  for (const [k, v] of Object.entries(params)) {
    str = str.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
  }
  return str;
}

export function translate(
  language: string,
  key: TranslationKey,
  params?: Record<string, string | number>
): string {
  const dict = TRANSLATIONS[language] || TRANSLATIONS.pt;
  return formatTranslation(dict[key] || TRANSLATIONS.pt[key] || key, language, params);
}

export const PageLanguageContext = createContext<SupportedLanguage | null>(null);

export function useTranslation() {
  const pageLanguage = useContext(PageLanguageContext);
  const storeLanguage = useUiStore((state) => state.language) || "pt";
  const language = pageLanguage ?? storeLanguage;
  const setLanguage = useUiStore((state) => state.setLanguage);

  const t = (key: TranslationKey, params?: Record<string, string | number>): string =>
    translate(language, key, params);

  return { t, language, setLanguage, textDir: textDirection(language) };
}

export function localizeErrorMessage(
  msg: string | null | undefined,
  t: (key: TranslationKey, params?: Record<string, string | number>) => string
): string {
  if (!msg) return "";
  const byCode: Partial<Record<string, TranslationKey>> = {
    NOTE_TOO_LARGE: "note_too_large",
    google_account_mismatch: "google_account_mismatch",
    google_account_in_use: "google_account_in_use",
    google_token_invalid: "google_token_invalid",
    google_scope_missing: "google_scope_missing",
    rate_limited: "rate_limited",
    payload_too_large: "ai_payload_too_large",
    unauthorized: "auth_error_session",
  };
  const coded = byCode[msg.trim()];
  if (coded) return t(coded);
  if (msg.startsWith("Falhou:") || msg.startsWith("Failed:")) {
    const cleaned = msg.replace(/^(Falhou|Failed):s*/i, "");
    return localizeErrorMessage(cleaned, t) || t("status_failed");
  }
  if (msg.includes("TOKEN_ENCRYPTION_KEY")) {
    return t("token_encryption_key_missing");
  }
  if (msg.includes("FIREBASE_SERVICE_ACCOUNT_JSON")) {
    if (msg.toLowerCase().includes("salvar") || msg.toLowerCase().includes("save")) {
      return t("firebase_admin_not_configured_save");
    }
    return t("firebase_admin_not_configured_set_env");
  }
  if (msg.toLowerCase().includes("firebase admin n") || msg.toLowerCase().includes("firebase admin not configured")) {
    return t("firebase_admin_not_configured");
  }
  if (msg === "guest_account_required") {
    return t("integration_requires_account");
  }
  if (msg === "google_access_token_missing") {
    return t("google_access_token_missing");
  }
  if (msg.includes("conta do Evernote não está conectada")) {
    return t("evernote_not_connected");
  }
  if (msg.includes("sessão do Evernote expirou")) {
    return t("evernote_session_expired");
  }
  if (msg.includes("não expõe uma ferramenta")) {
    return t("evernote_tool_unavailable");
  }
  if (msg.includes("servidor de autorização do Evernote")) {
    return t("evernote_discovery_failed");
  }
  if (msg.includes("conta do Google não está conectada")) {
    return t("google_not_connected");
  }
  if (msg.includes("sessão do Google expirou")) {
    return t("google_session_expired");
  }
  if (msg.includes("não está conectada") || msg.includes("not connected")) {
    return t("notion_not_connected");
  }
  if (msg.includes("Token do Notion ausente") || msg.includes("Notion token missing")) {
    return t("notion_token_missing");
  }
  if (msg.includes("Não foi possível ler o workspace") || msg.includes("Could not read Notion workspace")) {
    return t("notion_tree_read_error");
  }
  if (msg.includes("Importação concluída") || msg.toLowerCase().includes("import completed")) {
    return t("import_completed");
  }
  if (msg.includes("Lendo estrutura") || msg.toLowerCase().includes("discovering")) {
    return t("wizard_status_discovering");
  }
  if (msg.includes("Reconstruindo backlinks") || msg.toLowerCase().includes("backlinks")) {
    return t("wizard_status_backlinks");
  }
  if (msg.includes("Job enfileirado") || msg.toLowerCase().includes("enfileirado")) {
    return t("wizard_status_queued");
  }
  if (msg.includes("Preparando") || msg.toLowerCase().includes("preparing")) {
    return t("wizard_status_preparing");
  }
  if (msg.includes("Cancelado pelo usuário") || msg.includes("Cancelada") || msg.toLowerCase().includes("canceled")) {
    return t("status_canceled");
  }
  if (msg.includes("Vídeo longo demais") || msg.includes("Vídeo muito grande")) {
    // O limite viaja dentro da mensagem de erro, para a tradução nunca ficar
    // presa a um número fixo.
    const limit = msg.match(/(\d+)\s*MB/i)?.[1];
    if (!limit) return t("file_attach_error");
    return msg.includes("longo demais")
      ? t("video_too_long", { limit })
      : t("video_too_large", { limit });
  }
  if (
    msg.includes("continua acima de") ||
    msg.includes("muito grande para ser comprimido") ||
    msg.includes("Tente um arquivo menor")
  ) {
    return t("file_attach_error");
  }
  if (msg.includes("Não foi possível comprimir") || msg.includes("Não foi possível salvar o áudio")) {
    return t("audio_save_error");
  }
  return msg;
}
